insert into public.proposals (id, user_id, scope, session_id, status, payload) values
  ('proposal-1', '00000000-0000-0000-0000-000000000001', 'day', 'wed-400s', 'proposed', '{"headline":"Ease off today.","subhead":"Swap the 400s for an easy 4 miles.","rationale":"Readiness is down nine points and your Achilles flagged mild yesterday. A lighter day keeps the build on schedule without compounding load on the tendon — we''ll reassess in the morning.","badge":"HOLD","before":{"id":"wed-400s","date":"2026-07-01","type":"speed","title":"Rolling 400s","detail":"Intervals · 4.5 mi · ~45 min","distanceMi":4.5,"paceTarget":"5K pace","zone":"Zone 4–5","status":"planned","provenance":"original","structure":[{"kind":"warmup","label":"Warm up","zone":"Zone 2","pace":"Easy","duration":"10:00"},{"kind":"rep","label":"400m hard","zone":"Zone 5","pace":"5K pace","duration":"1:32","repeat":8},{"kind":"recovery","label":"200m float","zone":"easy","pace":"Recovery","duration":"1:05"},{"kind":"cooldown","label":"Cool down","zone":"Zone 1","pace":"Easy","duration":"10:00"}]},"after":{"id":"wed-400s","date":"2026-07-01","type":"easy","title":"Easy","detail":"4 mi · Zone 2 · 9:30/mi","distanceMi":4,"paceTarget":"9:30/mi","zone":"Zone 2","status":"planned","provenance":"accepted-proposal"},"drivers":[{"label":"HRV","value":"48","deltaPct":-12,"tone":"negative"},{"label":"SLEEP","value":"6:12","deltaText":"−1:32","tone":"negative"},{"label":"ACHILLES","value":"2/10 mild","tone":"warning"}],"reviewedAt":"6:41 AM"}'::jsonb),
  ('proposal-2', '00000000-0000-0000-0000-000000000001', 'week', 'sun-long', 'proposed', '{"headline":"Move long run to Saturday","subhead":"Rain forecast Sunday — shift the 12 miler.","rationale":"Heavy rain is forecast for Sunday morning. Moving the long run to Saturday keeps the key session intact without the weather risk.","badge":"ADJUST","before":{"id":"sun-long","date":"2026-07-05","type":"long","title":"Long run","detail":"12 mi · Zone 2–3","distanceMi":12,"zone":"Zone 2–3","status":"planned","provenance":"original"},"after":{"id":"sat-long-moved","date":"2026-07-04","type":"long","title":"Long run","detail":"12 mi · Zone 2–3 · moved from Sunday","distanceMi":12,"zone":"Zone 2–3","status":"planned","provenance":"original"},"drivers":[{"label":"WEATHER","value":"Rain · Sun","tone":"warning"},{"label":"LONG RUN","value":"12 mi","tone":"neutral"}],"reviewedAt":"6:41 AM"}'::jsonb),
  ('proposal-3', '00000000-0000-0000-0000-000000000001', 'workout', 'wed-400s', 'proposed', '{"headline":"Try 5 × 600m instead","subhead":"Same time in Zone 5, fewer hard accelerations.","rationale":"Same time in Zone 5 with fewer hard transitions — easier on turnover at nearly the same total time.","badge":"ADJUST","before":{"id":"wed-400s","date":"2026-07-01","type":"speed","title":"Rolling 400s","detail":"Intervals · 4.5 mi · ~45 min","distanceMi":4.5,"paceTarget":"5K pace","zone":"Zone 4–5","status":"planned","provenance":"original","structure":[{"kind":"warmup","label":"Warm up","zone":"Zone 2","pace":"Easy","duration":"10:00"},{"kind":"rep","label":"400m hard","zone":"Zone 5","pace":"5K pace","duration":"1:32","repeat":8},{"kind":"recovery","label":"200m float","zone":"easy","pace":"Recovery","duration":"1:05"},{"kind":"cooldown","label":"Cool down","zone":"Zone 1","pace":"Easy","duration":"10:00"}]},"after":{"id":"wed-400s","date":"2026-07-01","type":"speed","title":"Rolling 600s","detail":"5 × 600m · ~44 min","distanceMi":4.5,"paceTarget":"5K pace","zone":"Zone 4–5","status":"planned","provenance":"modified-proposal","structure":[{"kind":"warmup","label":"Warm up","zone":"Zone 2","pace":"Easy","duration":"10:00"},{"kind":"rep","label":"600m hard","zone":"Zone 5","pace":"5K pace","duration":"2:18","repeat":5},{"kind":"recovery","label":"200m float","zone":"easy","pace":"Recovery","duration":"1:05"},{"kind":"cooldown","label":"Cool down","zone":"Zone 1","pace":"Easy","duration":"10:00"}]},"drivers":[{"label":"REPS","value":"5×600m","tone":"neutral"},{"label":"TIME","value":"~44 min","tone":"neutral"},{"label":"ZONE 5","value":"same Z5 time","tone":"neutral"}],"reviewedAt":"6:41 AM","chatHeadline":"5 × 600m at 10K pace"}'::jsonb);
